const size_t hash1 = ckh->hash_function(key, ckh->key_size, ckh->hash_seed1) & ckh->hash_mask;
    const size_t hash2 = ckh->hash_function(key, ckh->key_size, ckh->hash_seed2) & ckh->hash_mask;

    // Try to insert directly into either bucket
    ckh_slot_t *slot1 = &ckh->slots[hash1];
    ckh_slot_t *slot2 = &ckh->slots[hash2];

    if (!slot1->occupied) {
        slot1->occupied = true;
        std::memcpy(slot1->key, key, ckh->key_size);
        std::memcpy(slot1->data, data, ckh->data_size);
        ckh->count++;
        return false;
    }
    if (!slot2->occupied) {
        slot2->occupied = true;
        std::memcpy(slot2->key, key, ckh->key_size);
        std::memcpy(slot2->data, data, ckh->data_size);
        ckh->count++;
        return false;
    }

    // Both buckets are occupied, try cuckoo eviction
    ckh_slot_t *current_slot = slot1;
    void *current_key = current_slot->key;
    void *current_data = current_slot->data;
    size_t current_hash = hash1;
    size_t eviction_count = 0;

    while (eviction_count < ckh->max_eviction_attempts) {
        // Calculate alternative hash for current key
        size_t alt_hash = ckh->hash_function(current_key, ckh->key_size, ckh->hash_seed1 + ckh->hash_seed2 - current_hash) & ckh->hash_mask;
        ckh_slot_t *alt_slot = &ckh->slots[alt_hash];

        if (!alt_slot->occupied) {
            // Found empty slot, perform eviction
            alt_slot->occupied = true;
            std::memcpy(alt_slot->key, current_key, ckh->key_size);
            std::memcpy(alt_slot->data, current_data, ckh->data_size);

            // Insert new key-data pair
            current_slot->occupied = true;
            std::memcpy(current_slot->key, key, ckh->key_size);
            std::memcpy(current_slot->data, data, ckh->data_size);
            ckh->count++;
            return false;
        }

        // Swap current with alt slot
        std::swap(current_key, alt_slot->key);
        std::swap(current_data, alt_slot->data);
        current_hash = alt_hash;
        current_slot = alt_slot;
        eviction_count++;
    }

    // Couldn't insert after max eviction attempts, need to grow
    return true;
    // END_CODE

